def process(load_all):
    import pandas as pd
    import numpy as np

    df = load_all.copy()

    # Map each source_file to its date column and one or more enterococcus columns (already in unioned frame)
    configs = {
        'carson_beach_datasheet.csv': {
            'beach': 'Carson Beach',
            'date_col': 'Carson Beach, South Boston: Bacterial Water Quality',
            'enter_cols': ['Unnamed: 5', 'Unnamed: 7'],
        },
        'city_point_beach_datasheet.csv': {
            'beach': 'City Point Beach',
            'date_col': 'City Point Beach, South Boston: Bacterial Water Quality',
            'enter_cols': ['Unnamed: 5', 'Unnamed: 7'],
        },
        'constitution_beach_datasheet.csv': {
            'beach': 'Constitution Beach',
            'date_col': 'Constitution Beach, East Boston: Bacterial Water Quality',
            'enter_cols': ['Unnamed: 5', 'Unnamed: 7', 'Unnamed: 9'],
        },
        'm_street_beach_datasheet.csv': {
            'beach': 'M Street Beach',
            'date_col': 'M Street Beach, South Boston: Bacterial Water Quality',
            'enter_cols': ['Unnamed: 5', 'Unnamed: 7'],
        },
        'malibu_beach_datasheet.csv': {
            'beach': 'Malibu Beach',
            'date_col': 'Malibu Beach, Dorchester: Bacterial Water Quality',
            'enter_cols': ['Unnamed: 5', 'Unnamed: 7'],
        },
        'tenean_beach_datasheet.csv': {
            'beach': 'Tenean Beach',
            'date_col': 'Tenean Beach, Dorchester: Bacterial Water Quality',
            'enter_cols': ['Unnamed: 5', 'Unnamed: 7', 'Unnamed: 9'],
        },
        'wollaston_beach_datasheet.csv': {
            'beach': 'Wollaston Beach',
            'date_col': 'Wollaston Beach, Quincy: Bacterial Water Quality',
            'enter_cols': ['Unnamed: 5', 'Unnamed: 7', 'Unnamed: 9', 'Unnamed: 11'],
        },
        'pleasure_bay_and_castle_island_beach_datasheet.csv': {
            'beach': None,  # handled separately: Pleasure Bay & Castle Island in one file
            'date_col': 'Pleasure Bay Beach, South Boston: Bacterial Water Quality',
            'enter_cols': ['Unnamed: 5', 'Unnamed: 7', 'Unnamed: 9'],
        },
    }

    out_parts = []

    for sf, cfg in configs.items():
        sub = df[df['source_file'] == sf].copy()
        date_raw = sub[cfg['date_col']]

        # Drop header/label rows (where date isn't parseable)
        date = pd.to_datetime(date_raw, errors='coerce')

        def parse_enter(s):
            if pd.isna(s):
                return np.nan
            s = str(s).strip()
            if s.lower() == 'null' or s == '':
                return np.nan
            # treat '< x' as x (conservative for passing threshold since x is small here)
            if s.startswith('<'):
                s = s.replace('<', '').strip()
            if s.startswith('>'):
                s = s.replace('>', '').strip()
            try:
                return float(s)
            except Exception:
                return np.nan

        enter_vals = []
        for c in cfg['enter_cols']:
            if c in sub.columns:
                enter_vals.append(sub[c].map(parse_enter))
        if not enter_vals:
            continue
        enter_df = pd.concat(enter_vals, axis=1)
        # If multiple stations per date, consider worst (max) enterococcus
        enter_max = enter_df.max(axis=1, skipna=True)

        beach_name = cfg['beach']
        if sf == 'pleasure_bay_and_castle_island_beach_datasheet.csv':
            # Distinguish using tag/location columns: Unnamed:4 / Unnamed:6 / Unnamed:8 carry station names.
            # Castle Island stations include 'Castle Island' in those tag columns.
            tag_cols = [c for c in ['Unnamed: 4', 'Unnamed: 6', 'Unnamed: 8'] if c in sub.columns]
            tag_text = sub[tag_cols].astype(str).agg(' '.join, axis=1) if tag_cols else pd.Series('', index=sub.index)
            is_castle = tag_text.str.contains('Castle Island', case=False, na=False)
            beach_series = pd.Series(np.where(is_castle, 'Castle Island Beach', 'Pleasure Bay Beach'), index=sub.index)
        else:
            beach_series = pd.Series(beach_name, index=sub.index)

        tidy = pd.DataFrame({
            'beach': beach_series,
            'date': date,
            'enterococcus': enter_max
        })
        tidy = tidy.dropna(subset=['date'])
        out_parts.append(tidy)

    out = pd.concat(out_parts, ignore_index=True)

    # Keep years 2020-2024 inclusive
    out = out[(out['date'].dt.year >= 2020) & (out['date'].dt.year <= 2024)]

    return out
